import React, { useState, useEffect } from 'react';
import { 
  Bot, 
  FileText, 
  CheckCircle, 
  AlertCircle, 
  Clock,
  TrendingUp,
  FolderOpen,
  Activity,
  Play,
  Square,
  RotateCcw
} from 'lucide-react';
import { useBot } from '../contexts/BotContext';

const Dashboard = () => {
  const { 
    botStatus, 
    processedFiles, 
    totalFiles, 
    realTimeUpdates,
    logs 
  } = useBot();

  // State สำหรับการทดสอบระบบ
  const [testResults, setTestResults] = useState(null);
  const [isRunningTest, setIsRunningTest] = useState(false);
  const [testLogs, setTestLogs] = useState([]);
  const [testOutput, setTestOutput] = useState([]);

  const stats = [
    {
      title: 'สถานะบอท',
      value: botStatus === 'running' ? 'กำลังทำงาน' : 'หยุดทำงาน',
      icon: Bot,
      color: botStatus === 'running' ? 'text-success-600' : 'text-gray-600',
      bgColor: botStatus === 'running' ? 'bg-success-100' : 'bg-gray-100'
    },
    {
      title: 'ไฟล์ที่ประมวลผล',
      value: `${processedFiles}/${totalFiles}`,
      icon: FileText,
      color: 'text-primary-600',
      bgColor: 'bg-primary-100'
    },
    {
      title: 'ความคืบหน้า',
      value: `${Math.round((processedFiles / Math.max(totalFiles, 1)) * 100)}%`,
      icon: TrendingUp,
      color: 'text-warning-600',
      bgColor: 'bg-warning-100'
    },
    {
      title: 'การทำงานล่าสุด',
      value: realTimeUpdates.lastUpdate ? 
        new Date(realTimeUpdates.lastUpdate).toLocaleTimeString('th-TH') : 
        'ไม่มีข้อมูล',
      icon: Clock,
      color: 'text-info-600',
      bgColor: 'bg-info-100'
    }
  ];

  const recentLogs = logs.slice(-5).reverse();

  // Polling สำหรับผลการทดสอบ - เร็วขึ้นมาก!
  useEffect(() => {
    let interval;
    
    if (isRunningTest) {
      interval = setInterval(async () => {
        try {
          const response = await fetch('/api/test-status');
          const data = await response.json();
          
          if (data.status === 'completed') {
            setIsRunningTest(false);
            setTestResults(data.results);
            addTestLog('success', 'การทดสอบเสร็จสิ้น');
            // หยุด polling ทันที
            return;
          } else if (data.status === 'running') {
            // อัปเดต output แบบ real-time ทันที
            setTestOutput(data.output || []);
          }
        } catch (error) {
          console.error('Error polling test status:', error);
        }
      }, 10); // Poll ทุก 10ms - เร็วขึ้น 25 เท่า!
    }
    
    return () => {
      if (interval) {
        clearInterval(interval);
      }
    };
  }, [isRunningTest]);

  // Auto-scroll to bottom of terminal - เร็วขึ้น
  useEffect(() => {
    const terminalContent = document.querySelector('.terminal-content');
    if (terminalContent) {
      // ใช้ requestAnimationFrame เพื่อให้ smooth ขึ้น
      requestAnimationFrame(() => {
        terminalContent.scrollTop = terminalContent.scrollHeight;
      });
    }
  }, [testOutput]);

  // ฟังก์ชันรันการทดสอบระบบ
  const runSystemTest = async (testType) => {
    setIsRunningTest(true);
    setTestLogs([]);
    setTestResults(null);
    setTestOutput([]);

    try {
      // เพิ่ม log เริ่มต้น
      addTestLog('info', `เริ่มต้นการทดสอบ: ${testType}`);

      const response = await fetch('/api/run-test', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          test_type: testType,
          timestamp: new Date().toISOString()
        })
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      addTestLog('info', data.message);

    } catch (error) {
      addTestLog('error', `เกิดข้อผิดพลาด: ${error.message}`);
      setIsRunningTest(false);
      console.error('Error running test:', error);
    }
  };

  // ฟังก์ชันเพิ่ม log การทดสอบ
  const addTestLog = (level, message) => {
    const newLog = {
      id: Date.now(),
      level,
      message,
      timestamp: new Date()
    };
    setTestLogs(prev => [...prev, newLog]);
  };

  // ฟังก์ชันล้างผลการทดสอบ
  const clearTestResults = () => {
    setTestResults(null);
    setTestLogs([]);
    setTestOutput([]);
  };

  // ฟังก์ชันหยุดการทดสอบ
  const stopTest = async () => {
    try {
      await fetch('/api/stop-test', { method: 'POST' });
      addTestLog('warning', 'หยุดการทดสอบ');
      setIsRunningTest(false);
    } catch (error) {
      addTestLog('error', `ไม่สามารถหยุดการทดสอบได้: ${error.message}`);
    }
  };

  return (
    <div className="p-6">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900 mb-2">แดชบอร์ด</h1>
        <p className="text-gray-600">ภาพรวมการทำงานของระบบบอทอัตโนมัติ</p>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        {stats.map((stat, index) => (
          <div key={index} className="card">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">{stat.title}</p>
                <p className={`text-2xl font-bold ${stat.color}`}>{stat.value}</p>
              </div>
              <div className={`p-3 rounded-lg ${stat.bgColor}`}>
                <stat.icon className={`w-6 h-6 ${stat.color}`} />
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Progress Bar */}
      {totalFiles > 0 && (
        <div className="card mb-8">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-gray-900">ความคืบหน้าการประมวลผล</h3>
            <span className="text-sm text-gray-500">
              {processedFiles} จาก {totalFiles} ไฟล์
            </span>
          </div>
          <div className="w-full bg-gray-200 rounded-full h-3">
            <div 
              className="bg-primary-600 h-3 rounded-full transition-all duration-300"
              style={{ width: `${(processedFiles / totalFiles) * 100}%` }}
            ></div>
          </div>
          <p className="text-sm text-gray-600 mt-2">
            {realTimeUpdates.currentAction || 'รอการเริ่มต้น...'}
          </p>
        </div>
      )}

      {/* Quick Actions */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
        {/* Bot Control */}
        <div className="card">
          <div className="flex items-center space-x-3 mb-4">
            <Bot className="w-6 h-6 text-primary-600" />
            <h3 className="text-lg font-semibold text-gray-900">ควบคุมบอท</h3>
          </div>
          <div className="space-y-3">
            <button className="btn-success w-full">
              <Bot className="w-4 h-4 mr-2" />
              เริ่มการทำงาน
            </button>
            <button className="btn-warning w-full">
              <Clock className="w-4 h-4 mr-2" />
              หยุดชั่วคราว
            </button>
            <button className="btn-error w-full">
              <AlertCircle className="w-4 h-4 mr-2" />
              หยุดการทำงาน
            </button>
          </div>
        </div>

        {/* File Management */}
        <div className="card">
          <div className="flex items-center space-x-3 mb-4">
            <FolderOpen className="w-6 h-6 text-primary-600" />
            <h3 className="text-lg font-semibold text-gray-900">จัดการไฟล์</h3>
          </div>
          <div className="space-y-3">
            <button className="btn-primary w-full">
              <FileText className="w-4 h-4 mr-2" />
              อัปโหลดไฟล์
            </button>
            <button className="btn-secondary w-full">
              <Activity className="w-4 h-4 mr-2" />
              ดูสถานะไฟล์
            </button>
          </div>
        </div>

        {/* System Testing */}
        <div className="card">
          <div className="flex items-center space-x-3 mb-4">
            <div className="w-6 h-6 bg-green-600 rounded-lg flex items-center justify-center">
              <span className="text-white text-sm font-bold">🧪</span>
            </div>
            <h3 className="text-lg font-semibold text-gray-900">ทดสอบระบบ</h3>
          </div>
          <div className="space-y-3">
            <button 
              className="btn-success w-full"
              onClick={() => window.open('/back-to-top-examples', '_blank')}
            >
              <span className="mr-2">📋</span>
              ตัวอย่าง BackToTop
            </button>
            <button 
              className="btn-primary w-full"
              onClick={() => runSystemTest('test_system')}
              disabled={isRunningTest}
            >
              <span className="mr-2">🔍</span>
              {isRunningTest ? 'กำลังทดสอบ...' : 'ทดสอบระบบ Python'}
            </button>
            <button 
              className="btn-secondary w-full"
              onClick={() => runSystemTest('start_system')}
              disabled={isRunningTest}
            >
              <span className="mr-2">🚀</span>
              {isRunningTest ? 'กำลังเริ่มต้น...' : 'เริ่มต้นระบบ'}
            </button>
          </div>
        </div>
      </div>

      {/* Live System Testing */}
      <div className="card mb-8">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center space-x-3">
            <div className="w-8 h-8 bg-gradient-to-r from-green-500 to-blue-500 rounded-lg flex items-center justify-center">
              <span className="text-white text-lg">🧪</span>
            </div>
            <h3 className="text-lg font-semibold text-gray-900">การทดสอบระบบแบบ Real-time</h3>
          </div>
          <div className="flex space-x-2">
            {isRunningTest && (
              <button 
                onClick={stopTest}
                className="px-3 py-1 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors text-sm font-medium flex items-center"
              >
                <Square className="w-4 h-4 mr-1" />
                หยุด
              </button>
            )}
            <button 
              onClick={clearTestResults}
              className="px-3 py-1 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition-colors text-sm font-medium flex items-center"
            >
              <RotateCcw className="w-4 h-4 mr-1" />
              ล้าง
            </button>
          </div>
        </div>

        {/* Test Controls */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
          <div className="bg-gradient-to-br from-blue-50 to-indigo-50 p-4 rounded-lg border border-blue-200">
            <h4 className="font-semibold text-blue-900 mb-3 flex items-center">
              <span className="mr-2">🐍</span>
              ทดสอบระบบ Python
            </h4>
            <p className="text-blue-700 text-sm mb-3">
              รัน test_system.py เพื่อทดสอบ FileManager, WebAutomation และระบบไฟล์
            </p>
            <button 
              className="w-full bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              onClick={() => runSystemTest('test_system')}
              disabled={isRunningTest}
            >
              {isRunningTest ? (
                <span className="flex items-center justify-center">
                  <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                  กำลังทดสอบ...
                </span>
              ) : (
                <span className="flex items-center justify-center">
                  <Play className="w-4 h-4 mr-2" />
                  รันการทดสอบระบบ
                </span>
              )}
            </button>
          </div>

          <div className="bg-gradient-to-br from-green-50 to-emerald-50 p-4 rounded-lg border border-green-200">
            <h4 className="font-semibold text-green-900 mb-3 flex items-center">
              <span className="mr-2">🚀</span>
              เริ่มต้นระบบ
            </h4>
            <p className="text-green-700 text-sm mb-3">
              รัน start_system.py เพื่อเริ่มต้นระบบ BotV3 ทั้งหมด
            </p>
            <button 
              className="w-full bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              onClick={() => runSystemTest('start_system')}
              disabled={isRunningTest}
            >
              {isRunningTest ? (
                <span className="flex items-center justify-center">
                  <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                  กำลังเริ่มต้น...
                </span>
              ) : (
                <span className="flex items-center justify-center">
                  <Play className="w-4 h-4 mr-2" />
                  เริ่มต้นระบบ
                </span>
              )}
            </button>
          </div>
        </div>

        {/* Live Test Output */}
        {isRunningTest && testOutput.length > 0 && (
          <div className="bg-gray-50 rounded-lg p-4 mb-4">
            <h4 className="font-semibold text-gray-900 mb-3">ผลลัพธ์แบบ Real-time</h4>
            <div className="bg-gray-800 text-green-400 p-3 rounded-lg text-sm max-h-40 overflow-y-auto">
              {testOutput.map((line, index) => (
                <div key={index} className="font-mono">
                  {line}
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Real-time Terminal Display */}
        <div className="card mb-4">
          <div className="flex items-center justify-between mb-4">
            <h4 className="font-semibold text-gray-900 flex items-center">
              <span className="mr-2">💻</span>
              Terminal แบบ Real-time
            </h4>
            <div className="flex space-x-2">
              {isRunningTest && (
                <button 
                  onClick={stopTest}
                  className="px-3 py-1 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors text-sm font-medium flex items-center"
                >
                  <Square className="w-4 h-4 mr-1" />
                  หยุด
                </button>
              )}
              <button 
                onClick={clearTestResults}
                className="px-3 py-1 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition-colors text-sm font-medium flex items-center"
              >
                <RotateCcw className="w-4 h-4 mr-1" />
                ล้าง
              </button>
            </div>
          </div>
          
          {/* Terminal Window */}
          <div className="bg-black rounded-lg p-4 font-mono text-sm">
            {/* Terminal Header */}
            <div className="flex items-center space-x-2 mb-3 pb-2 border-b border-gray-700">
              <div className="flex space-x-2">
                <div className="w-3 h-3 bg-red-500 rounded-full"></div>
                <div className="w-3 h-3 bg-yellow-500 rounded-full"></div>
                <div className="w-3 h-3 bg-green-500 rounded-full"></div>
              </div>
              <span className="text-gray-400 ml-2">BotV3 Terminal</span>
            </div>
            
            {/* Terminal Content */}
            <div className="terminal-content text-green-400 min-h-64 max-h-96 overflow-y-auto">
              {isRunningTest ? (
                <>
                  {/* Command Line */}
                  <div className="mb-2">
                    <span className="text-blue-400">$</span>
                    <span className="text-white ml-2">
                      python {testResults?.test_type === 'test_system' ? 'test_system.py' : 'start_system.py'}
                    </span>
                  </div>
                  
                  {/* Live Output */}
                  {testResults ? (
                    // แสดงผลลัพธ์จาก testResults ทันที
                    <div className="text-green-400">
                      {testResults.output.split('\n').map((line, index) => (
                        <div key={index} className="text-green-400 mb-1">
                          {line}
                        </div>
                      ))}
                    </div>
                  ) : testOutput.length > 0 ? (
                    testOutput.map((line, index) => (
                      <div key={index} className="text-green-400 mb-1">
                        {line}
                      </div>
                    ))
                  ) : (
                    <div className="text-yellow-400 animate-pulse">
                      กำลังรัน script... กรุณารอสักครู่
                    </div>
                  )}
                  
                  {/* Cursor */}
                  <span className="text-green-400 animate-pulse">█</span>
                </>
              ) : (
                <>
                  {/* Welcome Message */}
                  <div className="text-blue-400 mb-2">
                    BotV3 Terminal v1.0
                  </div>
                  <div className="text-gray-400 mb-2">
                    พร้อมใช้งาน - คลิกปุ่มทดสอบเพื่อเริ่มต้น
                  </div>
                  <div className="text-gray-500 text-xs">
                    Available commands:
                  </div>
                  <div className="text-gray-500 text-xs ml-4">
                    • test_system - ทดสอบระบบหลัก
                  </div>
                  <div className="text-gray-500 text-xs ml-4">
                    • start_system - เริ่มต้นระบบ
                  </div>
                  <div className="text-gray-500 text-xs ml-4">
                    • clear - ล้างหน้าจอ
                  </div>
                </>
              )}
            </div>
          </div>
          
          {/* Terminal Controls */}
          <div className="mt-3 flex space-x-2">
            <button 
              onClick={() => runSystemTest('test_system')}
              disabled={isRunningTest}
              className="px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg text-sm font-medium disabled:opacity-50 disabled:cursor-not-allowed flex items-center"
            >
              <Play className="w-4 h-4 mr-2" />
              รัน test_system.py
            </button>
            <button 
              onClick={() => runSystemTest('start_system')}
              disabled={isRunningTest}
              className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-medium disabled:opacity-50 disabled:cursor-not-allowed flex items-center"
            >
              <Play className="w-4 h-4 mr-2" />
              รัน start_system.py
            </button>
          </div>
        </div>

        {/* Test Results Display */}
        {testResults && (
          <div className="bg-gray-50 rounded-lg p-4 mb-4">
            <h4 className="font-semibold text-gray-900 mb-3">ผลการทดสอบ</h4>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <p className="text-sm text-gray-600 mb-2">สถานะ:</p>
                <span className={`px-2 py-1 rounded-full text-sm font-medium ${
                  testResults.success ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                }`}>
                  {testResults.success ? 'สำเร็จ' : 'ล้มเหลว'}
                </span>
              </div>
              <div>
                <p className="text-sm text-gray-600 mb-2">เวลาที่ใช้:</p>
                <span className="text-sm font-medium text-gray-900">
                  {testResults.execution_time || 'N/A'} วินาที
                </span>
              </div>
            </div>
            {testResults.output && (
              <div className="mt-3">
                <p className="text-sm text-gray-600 mb-2">ผลลัพธ์:</p>
                <pre className="bg-gray-800 text-green-400 p-3 rounded-lg text-sm overflow-x-auto">
                  {testResults.output}
                </pre>
              </div>
            )}
            {testResults.error && (
              <div className="mt-3">
                <p className="text-sm text-gray-600 mb-2">ข้อผิดพลาด:</p>
                <pre className="bg-red-900 text-red-200 p-3 rounded-lg text-sm overflow-x-auto">
                  {testResults.error}
                </pre>
              </div>
            )}
          </div>
        )}

        {/* Test Logs */}
        {testLogs.length > 0 && (
          <div className="bg-gray-50 rounded-lg p-4">
            <h4 className="font-semibold text-gray-900 mb-3">บันทึกการทดสอบ</h4>
            <div className="space-y-2 max-h-40 overflow-y-auto">
              {testLogs.map((log) => (
                <div key={log.id} className="flex items-center space-x-3 p-2 bg-white rounded-lg">
                  <div className={`w-2 h-2 rounded-full ${
                    log.level === 'error' ? 'bg-red-500' :
                    log.level === 'warning' ? 'bg-yellow-500' :
                    log.level === 'success' ? 'bg-green-500' : 'bg-blue-500'
                  }`}></div>
                  <span className="text-sm text-gray-600 flex-1">{log.message}</span>
                  <span className="text-xs text-gray-500">
                    {log.timestamp.toLocaleTimeString('th-TH')}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Recent Logs */}
      <div className="card">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold text-gray-900">บันทึกการทำงานล่าสุด</h3>
          <button className="text-sm text-primary-600 hover:text-primary-700">
            ดูทั้งหมด
          </button>
        </div>
        <div className="space-y-3">
          {recentLogs.length > 0 ? (
            recentLogs.map((log, index) => (
              <div key={index} className="flex items-center space-x-3 p-3 bg-gray-50 rounded-lg">
                <div className={`w-2 h-2 rounded-full ${
                  log.level === 'error' ? 'bg-error-500' :
                  log.level === 'warning' ? 'bg-warning-500' :
                  log.level === 'success' ? 'bg-success-500' : 'bg-primary-500'
                }`}></div>
                <span className="text-sm text-gray-600 flex-1">{log.message}</span>
                <span className="text-xs text-gray-500">
                  {log.timestamp.toLocaleTimeString('th-TH')}
                </span>
              </div>
            ))
          ) : (
            <p className="text-gray-500 text-center py-4">ยังไม่มีบันทึกการทำงาน</p>
          )}
        </div>
      </div>

      {/* Additional Content for Testing BackToTop */}
      <div className="mt-8 space-y-6">
        <div className="card">
          <h3 className="text-lg font-semibold text-gray-900 mb-4">ข้อมูลเพิ่มเติมสำหรับทดสอบ</h3>
          <p className="text-gray-600 mb-4">
            เนื้อหานี้ถูกเพิ่มเข้ามาเพื่อทดสอบการทำงานของปุ่ม "กลับขึ้นด้านบน" 
            เมื่อคุณ scroll ลงมาดูเนื้อหาต่างๆ ปุ่มจะปรากฏขึ้นที่มุมขวาล่าง
          </p>
          
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="bg-blue-50 p-4 rounded-lg">
              <h4 className="font-medium text-blue-900 mb-2">การทำงานของระบบ</h4>
              <p className="text-blue-700 text-sm">
                ระบบ BotV3 ถูกออกแบบมาเพื่อจัดการไฟล์และทำงานอัตโนมัติบนเว็บไซต์ต่างๆ 
                โดยใช้เทคโนโลยี Selenium และ Playwright
              </p>
            </div>
            
            <div className="bg-green-50 p-4 rounded-lg">
              <h4 className="font-medium text-green-900 mb-2">ฟีเจอร์หลัก</h4>
              <p className="text-green-700 text-sm">
                - จัดการไฟล์อัตโนมัติ<br/>
                - อัปโหลดไฟล์ไปยังเว็บไซต์<br/>
                - ระบบบันทึกการทำงาน<br/>
                - แดชบอร์ดแบบ real-time
              </p>
            </div>
          </div>
        </div>

        <div className="card">
          <h3 className="text-lg font-semibold text-gray-900 mb-4">สถิติการใช้งาน</h3>
          <div className="space-y-4">
            <div className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
              <span className="text-gray-700">จำนวนไฟล์ที่ประมวลผลวันนี้</span>
              <span className="font-semibold text-gray-900">1,247</span>
            </div>
            <div className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
              <span className="text-gray-700">เวลาทำงานเฉลี่ยต่อไฟล์</span>
              <span className="font-semibold text-gray-900">2.3 วินาที</span>
            </div>
            <div className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
              <span className="text-gray-700">อัตราความสำเร็จ</span>
              <span className="font-semibold text-green-600">98.7%</span>
            </div>
          </div>
        </div>

        <div className="card">
          <h3 className="text-lg font-semibold text-gray-900 mb-4">การแจ้งเตือนล่าสุด</h3>
          <div className="space-y-3">
            <div className="flex items-center space-x-3 p-3 bg-yellow-50 rounded-lg">
              <div className="w-3 h-3 bg-yellow-500 rounded-full"></div>
              <span className="text-yellow-800">ระบบตรวจพบไฟล์ขนาดใหญ่ ต้องการการยืนยัน</span>
            </div>
            <div className="flex items-center space-x-3 p-3 bg-blue-50 rounded-lg">
              <div className="w-3 h-3 bg-blue-500 rounded-full"></div>
              <span className="text-blue-800">อัปเดตระบบเสร็จสิ้น เวอร์ชัน 3.2.1</span>
            </div>
            <div className="flex items-center space-x-3 p-3 bg-green-50 rounded-lg">
              <div className="w-3 h-3 bg-green-500 rounded-full"></div>
              <span className="text-green-800">การสำรองข้อมูลเสร็จสิ้น</span>
            </div>
          </div>
        </div>

        <div className="card">
          <h3 className="text-lg font-semibold text-gray-900 mb-4">คู่มือการใช้งาน</h3>
          <div className="prose prose-sm max-w-none">
            <p className="text-gray-600 mb-4">
              สำหรับการใช้งานระบบ BotV3 อย่างมีประสิทธิภาพ กรุณาอ่านคู่มือการใช้งานที่ครอบคลุมทุกฟีเจอร์
            </p>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <a href="#" className="block p-4 border border-gray-200 rounded-lg hover:border-blue-300 hover:bg-blue-50 transition-colors">
                <h5 className="font-medium text-gray-900 mb-2">คู่มือเริ่มต้น</h5>
                <p className="text-sm text-gray-600">เรียนรู้การใช้งานพื้นฐานของระบบ</p>
              </a>
              <a href="#" className="block p-4 border border-gray-200 rounded-lg hover:border-blue-300 hover:bg-blue-50 transition-colors">
                <h5 className="font-medium text-gray-900 mb-2">การตั้งค่าขั้นสูง</h5>
                <p className="text-sm text-gray-600">ปรับแต่งระบบตามความต้องการ</p>
              </a>
              <a href="#" className="block p-4 border border-gray-200 rounded-lg hover:border-blue-300 hover:bg-blue-50 transition-colors">
                <h5 className="font-medium text-gray-900 mb-2">การแก้ไขปัญหา</h5>
                <p className="text-sm text-gray-600">แก้ไขปัญหาที่พบบ่อย</p>
              </a>
            </div>
          </div>
        </div>

        <div className="card">
          <h3 className="text-lg font-semibold text-gray-900 mb-4">ข้อมูลการเชื่อมต่อ</h3>
          <div className="space-y-3">
            <div className="flex justify-between items-center">
              <span className="text-gray-600">สถานะเซิร์ฟเวอร์</span>
              <span className="px-2 py-1 bg-green-100 text-green-800 text-sm rounded-full">ออนไลน์</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-gray-600">เวลาตอบสนองเฉลี่ย</span>
              <span className="text-gray-900">45ms</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-gray-600">การเชื่อมต่อฐานข้อมูล</span>
              <span className="px-2 py-1 bg-green-100 text-green-800 text-sm rounded-full">เชื่อมต่อแล้ว</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-gray-600">พื้นที่จัดเก็บที่ใช้</span>
              <span className="text-gray-900">2.4 GB / 10 GB</span>
            </div>
          </div>
        </div>

        {/* การสนับสนุน */}
        <div className="card">
          <h3 className="text-lg font-semibold text-gray-900 mb-4">การสนับสนุน</h3>
          <p className="text-gray-600 mb-4">
            หากคุณพบปัญหาหรือต้องการความช่วยเหลือ กรุณาติดต่อทีมสนับสนุนของเรา
          </p>
          <div className="flex space-x-4">
            <button className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors">
              ติดต่อสนับสนุน
            </button>
            <button className="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors">
              ส่งข้อเสนอแนะ
            </button>
          </div>
        </div>
      </div>

      {/* Quick Testing Access */}
      <div className="card mt-8">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold text-gray-900">🚀 เข้าถึงการทดสอบระบบอย่างรวดเร็ว</h3>
          <span className="px-3 py-1 bg-yellow-100 text-yellow-800 text-sm rounded-full font-medium">
            แนะนำ
          </span>
        </div>
        
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="text-center p-4 bg-gradient-to-br from-purple-50 to-pink-50 rounded-lg border border-purple-200">
            <div className="w-12 h-12 bg-purple-600 rounded-full flex items-center justify-center mx-auto mb-3">
              <span className="text-white text-xl">🐍</span>
            </div>
            <h4 className="font-medium text-purple-900 mb-2">ทดสอบ Python</h4>
            <p className="text-purple-700 text-sm mb-3">ทดสอบระบบ backend และ automation</p>
            <button 
              className="w-full bg-purple-600 hover:bg-purple-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors"
              onClick={() => {
                const commands = [
                  'python test_system.py',
                  'python start_system.py',
                  'pip install -r requirements_flask.txt'
                ];
                alert('คำสั่งทดสอบระบบ:\n\n' + commands.map((cmd, i) => `${i+1}. ${cmd}`).join('\n'));
              }}
            >
              📋 ดูคำสั่ง
            </button>
          </div>

          <div className="text-center p-4 bg-gradient-to-br from-blue-50 to-cyan-50 rounded-lg border border-blue-200">
            <div className="w-12 h-12 bg-blue-600 rounded-full flex items-center justify-center mx-auto mb-3">
              <span className="text-white text-xl">⚛️</span>
            </div>
            <h4 className="font-medium text-blue-900 mb-2">ทดสอบ React</h4>
            <p className="text-blue-700 text-sm mb-3">ทดสอบ UI components และ BackToTop</p>
            <button 
              className="w-full bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors"
              onClick={() => window.open('/back-to-top-examples', '_blank')}
            >
              🎨 ทดสอบ UI
            </button>
          </div>

          <div className="text-center p-4 bg-gradient-to-br from-green-50 to-emerald-50 rounded-lg border border-green-200">
            <div className="w-12 h-12 bg-green-600 rounded-full flex items-center justify-center mx-auto mb-3">
              <span className="text-white text-xl">📚</span>
            </div>
            <h4 className="font-medium text-green-900 mb-2">เอกสารการทดสอบ</h4>
            <p className="text-green-700 text-sm mb-3">คู่มือและรายละเอียดการทดสอบ</p>
            <button 
              className="w-full bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors"
              onClick={() => {
                const files = [
                  'README_TESTING.md',
                  'README_BACK_TO_TOP.md',
                  'test_system.py',
                  'start_system.py'
                ];
                alert('ไฟล์เอกสารการทดสอบ:\n\n' + files.map((file, i) => `${i+1}. ${file}`).join('\n'));
              }}
            >
              📖 ดูเอกสาร
            </button>
          </div>
        </div>

        <div className="mt-6 p-4 bg-gray-50 rounded-lg">
          <h4 className="font-medium text-gray-900 mb-3">💡 เคล็ดลับการทดสอบ</h4>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm text-gray-600">
            <div>
              <p className="font-medium text-gray-700 mb-2">สำหรับ Python Backend:</p>
              <ul className="space-y-1">
                <li>• ตรวจสอบ dependencies ก่อน</li>
                <li>• รัน test_system.py เพื่อทดสอบ</li>
                <li>• ดูผลลัพธ์ใน console</li>
              </ul>
            </div>
            <div>
              <p className="font-medium text-gray-700 mb-2">สำหรับ React Frontend:</p>
              <ul className="space-y-1">
                <li>• Scroll ลงมาเพื่อดู BackToTop</li>
                <li>• ทดสอบในหน้าต่างๆ</li>
                <li>• ตรวจสอบ responsive design</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
